def shell(title,deck,body,path='',eyebrow='Filecraft guide',lang='en',home=False):
    c=COPY[lang]; labels=LABELS[lang]; plain=title.replace('<br>',' ');url=BASE+path
    languages=''.join(f'<a href="{p}" lang="{l}" hreflang="{l}"'+(' aria-current="page"' if l==lang and home else '')+f'>{label}</a>' for l,p,label in [('en','/','English'),('fr','/fr/','Français'),('es','/es/','Español')])
    alternates=''.join(f'<link rel="alternate" hreflang="{l}" href="{BASE+p}">' for l,p in [('en',''),('fr','fr/'),('es','es/'),('x-default','')]) if home else ''
    schema=json.dumps({'@context':'https://schema.org','@type':'SoftwareApplication','name':'Filecraft','url':BASE,'applicationCategory':'UtilitiesApplication','operatingSystem':'Windows, Linux, macOS; browser workspace','license':REPO+'/blob/main/LICENSE'})
    footer=''.join(f'<a href="/{p}/">{label}</a>' for p,label in zip(['privacy','cookies','releases','accessibility','licensing','contact'],labels['links']))
    intro='' if home else f'<div class="page-intro"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="deck">{deck}</p></div>'
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(plain)} | Filecraft</title><meta name="description" content="{esc(deck,quote=True)}"><link rel="canonical" href="{url}">{alternates}<meta property="og:type" content="website"><meta property="og:title" content="{esc(plain,quote=True)} | Filecraft"><meta property="og:description" content="{esc(deck,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/social-preview.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(plain,quote=True)} | Filecraft"><meta name="twitter:description" content="{esc(deck,quote=True)}"><meta name="twitter:image" content="{BASE}assets/social-preview.png"><script type="application/ld+json">{schema}</script><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script>{'<script src="/platform.js" defer></script>' if home else ''}</head><body class="{'landing' if home else 'guide-page'}"><a class="skip" href="#main">{labels['skip']}</a><header class="site-header"><a class="brand" href="/" aria-label="{labels['home']}">{MARK}<span>filecraft</span></a><nav aria-label="{labels['primary']}"><a href="/{'#what-it-does' if home and lang=='en' else 'features/'}">{c['features']}</a><a href="/download/">{c['downloads']}</a><a href="/documentation/">{c['guides']}</a></nav><div class="header-tools"><details class="languages"><summary aria-label="{c['lang']}"><svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg>{lang.upper()}<span aria-hidden="true">⌄</span></summary><div class="language-menu">{languages}</div></details><button class="theme-toggle" type="button" aria-label="{c['theme']}" hidden>◐</button><a class="nav-action" href="/workspace/">{c['open']} ↗</a></div></header><main id="main" tabindex="-1">{intro}{body}</main><footer class="site-footer"><div class="footer-top"><div><a class="brand" href="/">{MARK}<span>filecraft</span></a><p>{c['footer']}</p></div><nav aria-label="{labels['footer']}">{footer}<a href="{REPO}">GitHub ↗</a><a href="/brand/">{labels['assets']}</a></nav></div><div class="footer-bottom"><a href="/ai-disclosure/">{c['ai']}</a><p>{c['legal']}</p></div></footer></body></html>'''

def build_home():
    inventory=json.loads((ROOT/'downloads.json').read_text());win=next(a for a in inventory if a['platform']=='windows'); version=win['version']
    # The hero offers the visitor's own installer. Windows stays the static default so the
    # page still works without JavaScript; platform.js swaps the target to the detected
    # platform using the values embedded here, so there is one source of truth.
    linux=next((a for a in inventory if a['platform']=='linux'),None)
    mac_arm=next((a for a in inventory if a['platform']=='macos' and 'arm64' in a['name']),None)
    mac_intel=next((a for a in inventory if a['platform']=='macos' and 'x86_64' in a['name']),None)
    for lang,c in COPY.items():
        panels=''.join(f'<button type="button" class="scene-tab" data-scene="{i}" aria-pressed="{str(i==1).lower()}"><span>0{i}</span>{c["tab"+str(i)]}</button>' for i in range(1,4))
        faqs=''.join(f'<details><summary>{c["q"+str(i)]}</summary><p>{c["a"+str(i)]}</p></details>' for i in range(1,5))
        stories=''.join(f'<article><span class="story-number">0{i}</span><div><h3>{c["p"+str(i)]}</h3><p>{c["d"+str(i)]}</p></div><a class="round-link" href="{href}" aria-label="{c["p"+str(i)]}">↗</a></article>' for i,href in [(1,'/desktop/'),(2,'/workspace/'),(3,'/supported-formats/')])
        # The localised prefix is reused verbatim from the existing string, so no new
        # translation is invented; platform and architecture names come from the inventory.
        prefix=c['download'].replace('Windows','').strip()
        hero=[('windows',win,c['download']),
              ('linux',linux,f"{prefix} Linux ({linux['architecture']})" if linux else None),
              ('macos-arm64',mac_arm,f"{prefix} macOS ({mac_arm['architecture']})" if mac_arm else None),
              ('macos-x86',mac_intel,f"{prefix} macOS ({mac_intel['architecture']})" if mac_intel else None)]
        hero_urls={k:a['url'] for k,a,_ in hero if a}
        hero_labels={k:l for k,a,l in hero if a and l}
        body=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span>{c['tag']}</p><h1>{c['title']}</h1><p class="deck">{c['deck']}</p><div class="hero-actions"><a class="button" href="{win['url']}" data-download-urls="{esc(json.dumps(hero_urls),quote=True)}" data-download-labels="{esc(json.dumps(hero_labels),quote=True)}"><svg aria-hidden="true" width="16" height="16" viewBox="0 0 20 20" fill="currentColor"><path d="M1 2h8v7H1Zm10 0h8v7h-8ZM1 11h8v7H1Zm10 0h8v7h-8Z"/></svg><span class="hero-download-label">{c['download']}</span><span aria-hidden="true">↓</span></a><a class="secondary-link" href="/workspace/">{c['tryit']} ↗</a></div><a class="other-downloads" href="/download/">{c['other']}</a><p class="hero-note">{c['note']}</p><p class="release-note">{c['release']} {version}<br>{c['warning']}</p></div><div class="paper-scene" data-step="1"><div class="scene-top"><span>FILECRAFT / 01</span><span class="scene-orbit" aria-hidden="true">✳</span></div><div class="paper-stack" aria-hidden="true"><div class="sheet sheet-back"><span>PDF</span><div class="paper-lines"></div></div><div class="sheet sheet-mid"><span>{c['doc']}</span><div class="paper-lines"></div></div><div class="sheet sheet-front"><div class="sheet-header">{MARK}<span>01 / 02</span></div><div class="sheet-title">{c['paper']}</div><div class="paper-lines"></div><div class="paper-signature">Filecraft</div><span class="paper-stamp">PDF</span></div><span class="file-chip chip-one">.pdf</span><span class="file-chip chip-two">.jpg</span><span class="saved-chip">✓ {c['saved']}</span></div><div class="scene-bottom"><h2>{c['preview']}</h2><p class="scene-status" aria-live="polite" data-state1="{c['state1']}" data-state2="{c['state2']}" data-state3="{c['state3']}">{c['state1']}</p><div class="scene-tabs" hidden>{panels}</div><p class="illustration-note">{c['previewnote']}</p></div></div></section><div class="platform-strip"><span>Windows</span><span>macOS</span><span>Linux</span><span>{LABELS[lang]['browser']}</span><span class="strip-end">PDF · JPG · PNG · DOCX +</span></div><section class="everyday" id="what-it-does"><div><p class="eyebrow">FILECRAFT</p><h2>{c['section']}</h2><a class="text-link" href="/features/">{c['features']} ↗</a></div><div class="story-list">{stories}</div></section><section class="workspace-feature"><div class="workspace-heading"><div><p class="eyebrow">{LABELS[lang]['inbrowser']}</p><h2>{c['real']}</h2></div><div><p>{c['realbody']}</p><a class="text-link" href="/workspace/">{c['open']} ↗</a></div></div><figure><a href="/workspace/"><img src="/assets/workspace-preview.webp" width="1440" height="1000" alt="{c['caption']}" loading="lazy"></a><figcaption>{c['caption']}</figcaption></figure></section><section class="privacy-feature"><div class="privacy-symbol" aria-hidden="true">{MARK}<span>LOCAL</span></div><div><p class="eyebrow">{LABELS[lang]['device']}</p><h2>{c['privacy']}</h2><p>{c['privacybody']}</p><a class="text-link" href="/privacy/">{c['privacylink']} ↗</a></div></section><section class="faq-section"><h2>{c['faq']}</h2><div>{faqs}<a class="text-link" href="/faq/">{LABELS[lang]['faq']} ↗</a></div></section><section class="closing"><div><h2>{c['closing']}</h2><p>{c['closingbody']}</p></div><a class="button" href="/workspace/">{c['tryit']} ↗</a></section><p class="locale-note" lang="{lang}">{c['localenote']}</p>'''
        path='' if lang=='en' else lang+'/'
        out=ROOT/path/'index.html';out.parent.mkdir(exist_ok=True)
        out.write_text(shell(c['title'],c['deck'],body,path=path,lang=lang,home=True))
